INSERT INTO public.timeline_entries (id, "position", published, created_at, updated_at, period, title, org, detail) VALUES ('b5315ed1-4b62-4001-89cd-da66c2ba7b1b', 0, true, '2026-09-05 12:34:35.999427+00', '2026-09-05 12:34:35.999427+00', '1999 — 2004', 'B.Tech. Computer Engineering, First Class Honours', 'Ladoke Akintola University of Technology (LAUTECH), Ogbomoso', 'Graduated top of his class, earning the Stephen Awokoya Scholarship for Science Education and a PTDF scholarship along the way.');
INSERT INTO public.timeline_entries (id, "position", published, created_at, updated_at, period, title, org, detail) VALUES ('02883adf-803e-4e81-8c83-1f729a108ba5', 1, true, '2026-09-05 12:34:35.999427+00', '2026-09-05 12:34:35.999427+00', '2006 — 2011', 'M.Sc. Computing Information Engineering · Ph.D. Computing', 'Robert Gordon University, Aberdeen, United Kingdom', 'Doctoral research in artificial intelligence, machine learning and natural language processing, backed by the UK ORSAS award. Followed by an EPSRC-sponsored postdoctoral fellowship in information retrieval.');
INSERT INTO public.timeline_entries (id, "position", published, created_at, updated_at, period, title, org, detail) VALUES ('2b5a1bca-22a9-426b-bf04-842b14e81e5e', 2, true, '2026-09-05 12:34:35.999427+00', '2026-09-05 12:34:35.999427+00', '2014', 'MIT Empowering the Teachers Fellow', 'Massachusetts Institute of Technology, Cambridge, USA', 'Selected for the MIT-ETT fellowship, preparing African engineering faculty to build graduates with world-class problem-solving capabilities.');
INSERT INTO public.timeline_entries (id, "position", published, created_at, updated_at, period, title, org, detail) VALUES ('bf89d4f3-2a3f-4b07-8559-85af9a06e832', 3, true, '2026-09-05 12:34:35.999427+00', '2026-09-05 12:34:35.999427+00', '2012 — 2023', 'Professor of Computer Engineering (Intelligent Systems)', 'Federal University Oye-Ekiti (FUOYE)', 'Rose to full Professor and served as FUOYE''s pioneer Director of Quality Assurance, shaping the university''s academic standards from the ground up.');
INSERT INTO public.timeline_entries (id, "position", published, created_at, updated_at, period, title, org, detail) VALUES ('234b1254-04de-4c3b-84b7-47cfd7090c9f', 4, true, '2026-09-05 12:34:35.999427+00', '2026-09-05 12:34:35.999427+00', 'April 2023', 'Executive Director, Digital Exploration & Technical Services', 'Galaxy Backbone Limited, Abuja', 'Joined Nigeria''s federal digital infrastructure company, leading technical services and digital exploration.');
INSERT INTO public.timeline_entries (id, "position", published, created_at, updated_at, period, title, org, detail) VALUES ('76117e5d-8cf9-4496-8793-8580f44852ae', 5, true, '2026-09-05 12:34:35.999427+00', '2026-09-05 12:34:35.999427+00', 'February 2024 — present', 'Managing Director / Chief Executive Officer', 'Galaxy Backbone Limited', 'Appointed by His Excellency, President Bola Ahmed Tinubu, to lead Nigeria''s digital backbone — the ICT and shared-services provider to the entire federal government.');
